text:
{
  "jobs": [
    {
      "text": "Поддерживать ежедневный телефонный контакт с пожилым отцом, который живёт отдельно в посёлке",
      "quote": "А вот с папой почти каждый день по телефону разговариваем. Ему 69, он живёт в посёлке."
    },
    {
      "text": "Быть на связи с отцом в предсказуемое время — он звонит к моменту, когда у неё автобус после смены",
      "quote": "Знает, во сколько у меня автобус после смены, и обычно звонит как раз в это время."
    },
    {
      "text": "Успокоить отца и подтвердить, что с ней всё в порядке, когда он напуган",
      "quote": "Я сначала сказала ему, что я на работе и со мной всё хорошо."
    },
    {
      "text": "Договориться с братом о взаимном подстраховочном канале связи для отца",
      "quote": "Вечером созвонились с моим братом и договорились, что, если папа не может до меня дозвониться, сразу набирает его."
    },
    {
      "text": "Настроить избранные контакты у отца, чтобы он звонил в первую очередь детям",
      "quote": "Избранные контакты у папы теперь начинаются с нас двоих."
    },
    {
      "text": "Оплачивать отцу банковские СМС, чтобы он видел списания",
      "quote": "Из похожего я оплачиваю папе СМС от банка, около 70 рублей в месяц."
    }
  ],
  "pains": [
    {
      "text": "Отец поверил мошенникам, услышал женский плач и решил, что с дочерью беда",
      "quote": "Оказалось, ему позвонили, он услышал женский плач и решил, что это я."
    },
    {
      "text": "Мошенник сообщил отцу про аварию и потребовал денег",
      "quote": "Потом какой-то мужчина сказал, что я попала в аварию и нужны деньги."
    },
    {
      "text": "Отец был готов немедленно ехать, но не знал, куда именно",
      "quote": "Папа ничего не перевёл, но, говорит, уже стоял в прихожей с ключами. Даже не знал, в какую больницу ехать."
    },
    {
      "text": "Тревога отца в те минуты, пока никто из детей не отвечает на звонок",
      "quote": "Беспокоит время, пока никто из нас не ответил."
    },
    {
      "text": "Она физически не может ответить на звонок во время работы у печи, а брат — за рулём",
      "quote": "У печи я звонка не услышу, брат бывает за рулём."
    },
    {
      "text": "Для неё короткая пауза — рутина, а для отца это время сильного страха за неё",
      "quote": "Для меня это просто десять минут до перерыва, а папа все эти десять минут может думать, что со мной беда."
    },
    {
      "text": "Просьба отца поговорить ещё немного — сигнал, насколько он был напуган",
      "quote": "А он попросил: «Ты ещё минутку поговори». Вот тогда до меня дошло, как он испугался."
    }
  ],
  "current_solutions": [
    {
      "text": "Правило: если отец не может дозвониться до неё — сразу набирает брата",
      "quote": "договорились, что, если папа не может до меня дозвониться, сразу набирает его"
    },
    {
      "text": "Избранные контакты у отца начинаются с детей",
      "quote": "Избранные контакты у папы теперь начинаются с нас двоих."
    },
    {
      "text": "Правило на случай звонков якобы от неё с просьбой о деньгах: положить трубку и самому перезвонить ей или брату",
      "quote": "Теперь у нас одно правило на случай, если звонят якобы от меня и просят денег. Он кладёт трубку и сам набирает меня или брата."
    },
    {
      "text": "Раньше просила отца пропускать звонки с незнакомых номеров",
      "quote": "Раньше я просила его пропускать звонки с незнакомых номеров."
    },
    {
      "text": "Оплачивает отцу банковские СМС примерно за 70 рублей в месяц",
      "quote": "Из похожего я оплачиваю папе СМС от банка, около 70 рублей в месяц."
    },
    {
      "text": "Однажды отключали банковские СМС, но по просьбе отца вернули",
      "quote": "Мы как-то их отключили, а он через неделю попросил вернуть."
    }
  ],
  "barriers": [
    {
      "text": "Барьер понимания: неясно, работает ли распознавание мошенников на кнопочном телефоне",
      "quote": "Мне сразу хочется уточнить, работает ли это на кнопочном телефоне."
    },
    {
      "text": "Барьер понимания: непонятно, что услышит сам отец, если звонок оборвётся — он может испугаться сильнее",
      "quote": "И ещё важно, что услышит сам папа. Если разговор про «аварию» просто оборвётся, он ведь ещё сильнее испугается."
    },
    {
      "text": "Барьер понимания: нужно, чтобы отцу объяснили, почему прервалась связь",
      "quote": "Хотелось бы, чтобы ему тоже объяснили, почему прервалась связь."
    },
    {
      "text": "Барьер выбора: отец в первую очередь спросит, смогут ли до него дозвониться покупатели, и если звонки начнут пропадать — попросит всё отключить",
      "quote": "Папа первым делом спросит, смогут ли до него дозвониться покупатели. Если начнут пропадать звонки, он попросит всё отключить."
    },
    {
      "text": "Барьер выбора: важно, куда придёт уведомление — СМС она увидит на перерыве, а в отдельное приложение может не заглядывать днями",
      "quote": "А мне важно, куда придёт уведомление. СМС я увижу на первом же перерыве, а в отдельное приложение могу два дня не заглядывать."
    },
    {
      "text": "Барьер оплаты: готовность платить обусловлена тем, что всё заработает на телефоне отца",
      "quote": "За защиту от звонков я бы так же спокойно добавила к его тарифу рублей 80 в месяц, если на его телефоне всё заработает."
    }
  ],
  "triggers": [
    {
      "text": "Три пропущенных звонка от отца во время перерыва",
      "quote": "В конце лета выхожу на перерыв, а у меня три пропущенных от папы."
    },
    {
      "text": "Первый вопрос отца при перезвоне — цела ли она",
      "quote": "Перезваниваю, и он первым делом спрашивает: «[имя], ты цела?»"
    },
    {
      "text": "Случай с мошенническим звонком отцу, где он поверил в аварию и уже стоял с ключами",
      "quote": "Папа ничего не перевёл, но, говорит, уже стоял в прихожей с ключами."
    },
    {
      "text": "Осознание, насколько сильно отец испугался, после его просьбы поговорить ещё минутку",
      "quote": "Вот тогда до меня дошло, как он испугался."
    },
    {
      "text": "Случай, когда отец пропустил звонок с незнакомого номера, а это оказались покупатели мёда, простоявшие у калитки полчаса",
      "quote": "Он один раз так и сделал, а потом выяснилось, что это люди за мёдом приехали и полчаса простояли у калитки."
    }
  ],
  "words": [
    "«[имя], ты цела?»",
    "«Ты ещё минутку поговори»",
    "«стоял в прихожей с ключами»",
    "«Даже не знал, в какую больницу ехать»",
    "«Избранные контакты»",
    "«одно правило»",
    "«кнопочный телефон»",
    "«пропускать звонки с незнакомых номеров»",
    "«у печи я звонка не услышу»",
    "«брат бывает за рулём»",
    "«десять минут до перерыва»",
    "«сервис распознает мошенника»",
    "«сам остановит звонок»",
    "«я получу сообщение»",
    "«разговор про „аварию“ просто оборвётся»",
    "«попросит всё отключить»",
    "«куда придёт уведомление»",
    "«СМС я увижу на первом же перерыве»",
    "«в отдельное приложение могу два дня не заглядывать»",
    "«рублей 80 в месяц»",
    "«если на его телефоне всё заработает»",
    "«у кассы посмотреть, сколько списали»"
  ],
  "surprises": [
    {
      "text": "Отец не перевёл деньги, но уже был готов ехать, не зная куда",
      "quote": "Папа ничего не перевёл, но, говорит, уже стоял в прихожей с ключами. Даже не знал, в какую больницу ехать."
    },
    {
      "text": "Просьба пропускать незнакомые номера привела к потере реальных покупателей мёда, которые полчаса стояли у калитки",
      "quote": "Он один раз так и сделал, а потом выяснилось, что это люди за мёдом приехали и полчаса простояли у калитки."
    },
    {
      "text": "Отец сам попросил вернуть отключённые банковские СМС через неделю",
      "quote": "Мы как-то их отключили, а он через неделю попросил вернуть."
    },
    {
      "text": "Готовность платить за защиту от звонков привязана к тому, что всё заработает именно на телефоне отца",
      "quote": "За защиту от звонков я бы так же спокойно добавила к его тарифу рублей 80 в месяц, если на его телефоне всё заработает."
    }
  ]
}
